CREATE TABLE feature_flags (key VARCHAR(180) PRIMARY KEY, value_type VARCHAR(20) NOT NULL, default_value JSONB NOT NULL, fail_safe_value JSONB NOT NULL, enabled BOOLEAN NOT NULL DEFAULT TRUE, environment VARCHAR(40) NOT NULL, rollout_bps INT NOT NULL DEFAULT 10000 CHECK(rollout_bps BETWEEN 0 AND 10000), rules_json JSONB NOT NULL DEFAULT '{}'::jsonb, version BIGINT NOT NULL DEFAULT 1, updated_by VARCHAR(120) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE feature_flag_versions (id BIGSERIAL PRIMARY KEY, flag_key VARCHAR(180) NOT NULL, version BIGINT NOT NULL, value_json JSONB NOT NULL, rules_json JSONB NOT NULL, changed_by VARCHAR(120) NOT NULL, changed_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE feature_flag_audit (id BIGSERIAL PRIMARY KEY, flag_key VARCHAR(180) NOT NULL, action VARCHAR(80) NOT NULL, actor_id VARCHAR(120) NOT NULL, before_json JSONB, after_json JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE feature_flag_outbox_events (id VARCHAR(120) PRIMARY KEY, aggregate_type VARCHAR(80) NOT NULL, aggregate_id VARCHAR(180) NOT NULL, event_type VARCHAR(120) NOT NULL, schema_version INT NOT NULL DEFAULT 1, occurred_at TIMESTAMPTZ NOT NULL, correlation_id VARCHAR(120) NOT NULL, payload_json JSONB NOT NULL, published_at TIMESTAMPTZ);
CREATE INDEX feature_flag_audit_key_idx ON feature_flag_audit(flag_key,created_at DESC);
